// Checks supabase/config.toml against docs/DEVELOPMENT.md §11.2, §11.3 and §13.2.
// Run from the repo root: npm run check:supabase
// The file is generated by `npx supabase init`; this guards the settings we rely on so that a
// CLI upgrade or a hand edit cannot silently turn off email confirmation or expose the app schema.
import { existsSync, readFileSync } from 'node:fs';

const CONFIG = 'supabase/config.toml';
const WEB_ORIGIN = 'http://localhost:5173';
/** Exact local redirect URLs. The web app's auth routes (task A19) must use these paths. */
const REDIRECT_URLS = [`${WEB_ORIGIN}/auth/callback`, `${WEB_ORIGIN}/auth/reset-password`];

/**
 * Minimal reader for the subset of TOML that config.toml uses: [section] headers and
 * `key = value` lines whose value is a string, number, boolean or array of strings
 * (arrays may span lines). Returns { "section.key": value }.
 */
function readToml(text) {
  const values = {};
  let section = '';
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = stripComment(lines[i]).trim();
    if (line === '') continue;
    const header = /^\[([^\]]+)\]$/.exec(line);
    if (header) {
      section = header[1].trim();
      continue;
    }
    const pair = /^([A-Za-z0-9_.-]+)\s*=\s*(.*)$/.exec(line);
    if (!pair) continue;
    let raw = pair[2];
    while (raw.startsWith('[') && !balanced(raw) && i + 1 < lines.length) {
      raw += ' ' + stripComment(lines[++i]).trim();
    }
    values[`${section}.${pair[1]}`] = parseValue(raw.trim());
  }
  return values;
}

function stripComment(line) {
  let inString = false;
  for (let i = 0; i < line.length; i++) {
    if (line[i] === '"' && line[i - 1] !== '\\') inString = !inString;
    if (line[i] === '#' && !inString) return line.slice(0, i);
  }
  return line;
}

function balanced(raw) {
  return (raw.match(/\[/g) ?? []).length === (raw.match(/\]/g) ?? []).length;
}

function parseValue(raw) {
  if (raw === 'true' || raw === 'false') return raw === 'true';
  if (/^-?\d+$/.test(raw)) return Number(raw);
  if (raw.startsWith('"')) return JSON.parse(raw);
  if (raw.startsWith('[')) return JSON.parse(raw.replace(/,\s*\]$/, ']'));
  return raw;
}

if (!existsSync(CONFIG)) {
  console.error(`✗ ${CONFIG} is missing. Run: npx supabase init (see README, task A8)`);
  process.exit(1);
}

const config = readToml(readFileSync(CONFIG, 'utf8'));
const errors = [];
const expect = (key, ok, message) => {
  if (!ok(config[key])) errors.push(`${key}: ${message} (found ${JSON.stringify(config[key])})`);
};

// Auth (§11.2)
expect('auth.enabled', (v) => v === true, 'Auth must be enabled');
expect('auth.site_url', (v) => v === WEB_ORIGIN, `must be ${WEB_ORIGIN}`);
expect(
  'auth.additional_redirect_urls',
  (v) =>
    Array.isArray(v) &&
    REDIRECT_URLS.every((url) => v.includes(url)) &&
    v.every((url) => typeof url === 'string' && !url.includes('*')),
  `must list exactly-matching URLs ${REDIRECT_URLS.join(', ')} and no wildcards`,
);
expect('auth.enable_signup', (v) => v === true, 'sign-up must be enabled');
expect(
  'auth.minimum_password_length',
  (v) => typeof v === 'number' && v >= 8,
  'must be at least 8',
);
expect(
  'auth.jwt_expiry',
  (v) => typeof v === 'number' && v <= 3600,
  'must be at most 3600 seconds',
);
expect('auth.enable_refresh_token_rotation', (v) => v === true, 'must be true');
expect('auth.email.enable_signup', (v) => v === true, 'email sign-up must be enabled');
expect('auth.email.enable_confirmations', (v) => v === true, 'email confirmation must be required');

// Local mail catcher, so confirmation and reset emails can be read at http://127.0.0.1:54324.
// The section is [local_smtp] in current CLI versions and was [inbucket] in older ones.
const mailCatcherKey = 'local_smtp.enabled' in config ? 'local_smtp.enabled' : 'inbucket.enabled';
expect(mailCatcherKey, (v) => v === true, 'the local mail catcher must be enabled');

// The private app schema must never be exposed through the Data API (§11.3, ADR-004)
for (const key of ['api.schemas', 'api.extra_search_path']) {
  expect(key, (v) => !Array.isArray(v) || !v.includes('app'), 'must not include the app schema');
}

if (errors.length) {
  console.error(errors.map((e) => `✗ ${e}`).join('\n'));
  process.exit(1);
}
console.log('Supabase config check passed');
